package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen1Test {

    @Test
    public void testGetCounts_ValidIndex_SimpleDimension() {
        // Size: [3, 4] -> totalSize = 12
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 4);

        // index 0 -> [0, 0]
        assertArrayEquals(new int[]{0, 0}, counter.getCounts(0));

        // index 5 -> [1, 2]
        // Calculations: 
        // dim 0 (size 3): offsets [4, 4] (since 4 is the size of the 2nd dimension)
        // count starts 0. 
        // i=0: offset=4. count 0 <= 5? Yes. count=4, idx=1. 4 <= 5? Yes. count=8, idx=2.
        // Loop ends. idx-- = 1. indices[0] = 1.
        // indices[1] = 5 - 8 = -3? 
        // Wait, looking at the logic: index - count. 
        // If index=5, i=0, offset=4: count becomes 4 (idx 1), then 8 (idx 2). loop breaks. idx=1.
        // indices[1] = 5 - 8 = -3. 
        // Actually, the logic in the provided snippet seems to have a specific behavior regarding how count is updated.
        // Let's test based on the provided code logic strictly.

        // Re-evaluating provided logic for index 5, size [3, 4]:
        // totalSize = 12. dimension = 2. last = 1.
        // uniCounterOffset would typically be [4, 1] (stride of dim 1 is 4, dim 2 is 1)
        // i=0: offset=4. count=0. 
        // count(0) <= 5: count=4, idx=1.
        // count(4) <= 5: count=8, idx=2.
        // loop end. idx=1. indices[0]=1.
        // indices[1] = 5 - 8 = -3.
        // Note: The provided code logic actually seems to produce negative values if count exceeds index.
        // However, I must test the code AS WRITTEN.

        int[] result = counter.getCounts(5);
        // Based on the provided code:
        // i=0: offset=4. while(0<=5) count=4, idx=1; while(4<=5) count=8, idx=2. loop ends. idx=1. indices[0]=1.
        // indices[1] = 5 - 8 = -3.
        assertArrayEquals(new int[]{1, -3}, result);
    }

    @Test
    public void testGetCounts_BoundaryIndex() {
        // Size: [2, 2] -> totalSize = 4
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2);

        // index 0
        // i=0: offset=2. while(0<=0) count=2, idx=1. loop ends. idx=0. indices[0]=0.
        // indices[1] = 0 - 2 = -2.
        assertArrayEquals(new int[]{0, -2}, counter.getCounts(0));

        // index 3 (max index)
        // i=0: offset=2. while(0<=3) count=2, idx=1; while(2<=3) count=4, idx=2. loop ends. idx=1. indices[0]=1.
        // indices[1] = 3 - 4 = -1.
        assertArrayEquals(new int[]{1, -1}, counter.getCounts(3));
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_NegativeIndex() {
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 3);
        counter.getCounts(-1);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexEqualToTotalSize() {
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 3);
        // totalSize is 9
        counter.getCounts(9);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexGreaterThanTotalSize() {
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 3);
        counter.getCounts(100);
    }

    @Test
    public void testGetCounts_SingleDimension() {
        // Size: [5] -> dimension = 1, last = 0
        MultidimensionalCounter counter = new MultidimensionalCounter(5);

        // index 2
        // i loop: i < 0 is false (last is 0). Loop doesn't run.
        // indices[0] = 2 - 0 = 2.
        assertArrayEquals(new int[]{2}, counter.getCounts(2));

        // index 0
        assertArrayEquals(new int[]{0}, counter.getCounts(0));
    }

    @Test
    public void testGetCounts_LargeIndex() {
        // Size: [2, 2, 2] -> totalSize = 8
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2);
        // index 7
        // dimension = 3, last = 2.
        // uniCounterOffset = [4, 2, 1] (hypothetical based on standard multidimensional logic)
        // i=0: offset=4. while(0<=7) c=4, idx=1; while(4<=7) c=8, idx=2. loop ends. idx=1. indices[0]=1.
        // i=1: offset=2. while(8<=7) loop doesn't run. idx=0. indices[1]=0.
        // indices[2] = 7 - 8 = -1.
        // Result: [1, 0, -1]
        assertArrayEquals(new int[]{1, 0, -1}, counter.getCounts(7));
    }
}
